  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks turn control of atomic motion and light into extraordinary frequency precision, enabling stringent tests of fundamental physics as well as timekeeping. This is a profound and durable achievement in precision measurement.",
        "attribution": "Katori's lattice-clock proposal and development and Ye's leading experimental realization and refinement are complementary central contributions.",
        "maturity": "The technique has been independently developed and improved over many years, with demonstrated performance and broad scientific use.",
        "uncertainties": [
          "The division of credit across the wider community that advanced clock performance deserves careful review."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum logic joined precise control of individual atoms with a scalable route to quantum computation, while also creating a powerful platform for fundamental quantum experiments.",
        "attribution": "Cirac and Zoller supplied seminal theoretical proposals; Blatt's experiments established and advanced the physical implementation. The theory and experimental demonstration form a persuasive shared achievement.",
        "maturity": "The foundational ideas and operations have been demonstrated, reproduced, and developed into increasingly capable systems over decades.",
        "uncertainties": [
          "The field's continuing expansion makes the boundary between the foundational achievement and later engineering advances important to define."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices made controlled experiments on strongly correlated quantum matter possible, giving many-body theory an unusually clean laboratory and revealing phases and dynamics otherwise difficult to access.",
        "attribution": "Zoller's theoretical vision and the experimental advances of Bloch and Greiner are complementary. Their distinct contributions should be tied to the specific foundational demonstrations being recognized.",
        "maturity": "The platform has produced sustained, reproducible research across many systems and continues to deepen understanding of correlated matter.",
        "uncertainties": [
          "The breadth of quantum simulation makes it difficult to identify a single bounded discovery and to separate foundational work from later developments."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Matter-wave interferometry brought atomic coherence to precision measurement, creating sensitive tests of gravity and other fundamental quantities while demonstrating the wave nature of matter in a powerful new regime.",
        "attribution": "Bordé, Pritchard, and Kasevich made important foundational contributions to atom interferometry. The award would need to specify which advances and experimental milestones define the shared achievement.",
        "maturity": "The methods have been independently developed, refined, and applied in precision experiments over several decades.",
        "uncertainties": [
          "The long development involved many groups, so the precise scope of the recognized invention needs careful delimitation."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "David A. Reis",
        "Rupert Huber",
        "Shambhu Ghimire"
      ],
      "assessment": {
        "nobel_worthiness": "High-harmonic generation in solids opened a surprising route to probing and controlling electron motion on ultrafast timescales, extending strong-field physics into condensed matter.",
        "attribution": "Ghimire's demonstrations and Reis's contributions to the early work, together with Huber's major advances in lightwave control and spectroscopy, represent central strands of this area. The specific discovery recognized should be stated precisely.",
        "maturity": "The phenomenon has been observed across materials and developed into a substantial experimental field, though its interpretive and control capabilities continue to evolve.",
        "uncertainties": [
          "The discovery's conceptual boundaries and the relative credit for its distinct experimental advances require careful review."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Eugene S. Polzik",
        "H. Jeff Kimble",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Light-matter interfaces and atomic memories made it possible to transfer and preserve quantum states between light and matter, a basic capability for quantum communication and a rich setting for studying quantum measurement.",
        "attribution": "Polzik, Kimble, and Lukin each made influential contributions to distinct interface and memory approaches. The particular foundational results linking them need clear definition.",
        "maturity": "The core interactions and memory protocols have been demonstrated repeatedly, although practical networks and long-distance capabilities remain under development.",
        "uncertainties": [
          "The broad topic spans several platforms and protocols, and its Nobel-scale unifying discovery is not sharply bounded."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B063",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "John D. Teufel",
        "Markus Aspelmeyer"
      ],
      "assessment": {
        "nobel_worthiness": "Preparing macroscopic mechanical motion in quantum states addresses a deep question about where quantum behavior remains observable and has opened new experimental tests of quantum measurement.",
        "attribution": "Cleland, Teufel, and Aspelmeyer made major contributions across different mechanical platforms. Credit should follow the specific demonstrations that achieved controlled quantum states and readout.",
        "maturity": "Several platforms have reached important quantum regimes, but the field is still advancing and the strongest claims depend on the precise scale and degree of quantum control demonstrated.",
        "uncertainties": [
          "The lasting conceptual impact of these demonstrations is still developing.",
          "The topic combines different platforms whose milestones may not constitute one single discovery."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light overcomes quantum noise limits in interferometric measurement and exemplifies how quantum states can improve precision beyond classical methods.",
        "attribution": "Caves established key theoretical foundations, Kimble advanced foundational demonstrations, and Schnabel helped bring squeezed light into large-scale interferometry. The theoretical and experimental contributions are distinct but connected.",
        "maturity": "Squeezed light has been repeatedly demonstrated and used to improve gravitational-wave detector sensitivity, a strong confirmation of practical and scientific importance.",
        "uncertainties": [
          "The work spans foundational theory, laboratory demonstrations, and later detector integration; the award's scope and credit boundary need precision."
        ]
      }
    }
  ]
